-- Bancada descartável. Nenhuma mensagem, nenhuma chamada de rede; rollback integral.
begin;
create temporary table d4 as select gen_random_uuid() shop,gen_random_uuid() person,gen_random_uuid() a,gen_random_uuid() b,gen_random_uuid() plan,gen_random_uuid() grp,gen_random_uuid() cycle,null::jsonb job,null::jsonb body,null::jsonb step;
create function pg_temp.check_d4(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select pg_temp.check_d4((select not enabled from public.whatsapp_care_cycle_policy),'Contrato novo não herda liberação do piloto anterior');
update public.whatsapp_send_controls set paused=false where scope='global';
update d4 set shop=(public.register_my_barbershop(gen_random_uuid(),'Ciclo Fictício','America/Sao_Paulo','single',true,'teste','teste','teste')->>'shop_id')::uuid;
select public.platform_create_whatsapp_channel(a,'Ciclo A') from d4;
select public.platform_create_whatsapp_channel(b,'Ciclo B') from d4;
update public.whatsapp_channels set display_phone=case id when (select a from d4) then '+5511800000111' else '+5511800000222' end,status='open' where id in(select a from d4 union all select b from d4);
select public.platform_confirm_whatsapp_control(id,routing_version,display_phone,instance_name,true) from public.whatsapp_channels where id in(select a from d4 union all select b from d4);
select public.platform_set_whatsapp_route(shop,null,0,a,b,null,'primary',false,false,false) from d4;
select pg_temp.check_d4((select jsonb_array_length(public.care_cycle_composition(shop))=2 from d4),'Composição da loja usa dois telefones físicos com controle confirmado');
insert into auth.users(id,email,raw_user_meta_data) select person,person||'@example.invalid','{}' from d4;
insert into public.memberships(user_id,barbershop_id,role) select person,shop,'customer' from d4;
insert into public.whatsapp_care_groups(id,barbershop_id,customer_id,customer_phone) select grp,shop,person,'+5511999999999' from d4;
insert into public.whatsapp_group_enrollments(group_id,profile_phone,profile_verified_at) select grp,null,null from d4;
insert into public.whatsapp_care_cycles(id,group_id,customer_phone,consented_numbers,creator_channel_id,creator_instance)
 select cycle,grp,'+5511999999999',public.care_cycle_composition(shop),(public.care_cycle_composition(shop)->0->>'id')::uuid,public.care_cycle_composition(shop)->0->>'instance' from d4;
update public.whatsapp_care_groups set current_cycle_id=(select cycle from d4) where id=(select grp from d4);
select pg_temp.check_d4((select not public.care_cycle_available(cycle) from d4),'Ter números e consentimento não ignora política desligada');
update public.whatsapp_care_cycle_policy set enabled=true;
select pg_temp.check_d4((select public.care_cycle_available(cycle) from d4),'Composição e adesão autenticada elegíveis para preparar, sem confirmar telefone');
update d4 set job=public.claim_care_cycle(cycle);
select pg_temp.check_d4((select job->>'token' is not null from d4),'Operador recebe posse com revisão fixada');
select pg_temp.check_d4((select public.claim_care_cycle(cycle) is null from d4),'Outra execução não toma lease em andamento');
update d4 set body=jsonb_build_object('operationId',job->>'creation_operation','cycleId',cycle,'subject','Notificações Ciclo Fictício • Cliente','customerJid','5511999999999@s.whatsapp.net','participants',jsonb_build_array(substring(job->'numbers'->1->>'phone' from 2)||'@s.whatsapp.net'),'brand',jsonb_build_object('shop_name','Ciclo Fictício','customer_name','Cliente','slug','ciclo-ficticio','timezone','America/Sao_Paulo'));
select public.seal_care_cycle_creation(cycle,(job->>'token')::uuid,'evo-ficticia',body,repeat('a',64)) from d4;
select public.seal_care_cycle_creation(cycle,(job->>'token')::uuid,'evo-ficticia',body,repeat('a',64)) from d4;
do $$begin begin perform public.seal_care_cycle_creation(cycle,(job->>'token')::uuid,'evo-ficticia',body||'{"subject":"Alterado"}',repeat('a',64)) from d4;raise exception 'FAIL: payload alterado aceito';exception when others then if sqlerrm like 'FAIL:%' then raise;end if;raise notice 'PASS: payload de criação não muda após ser lacrado';end;end $$;
update d4 set step=public.start_care_cycle_step(cycle,(job->>'token')::uuid,'create','initial',job->>'creator_instance',repeat('a',64));
select pg_temp.check_d4((select (step->>'execute')::boolean from d4),'Primeira execução recebe licença durável');
select pg_temp.check_d4((select (public.start_care_cycle_step(cycle,(job->>'token')::uuid,'create','initial',job->>'creator_instance',repeat('a',64))->>'execute')::boolean=false from d4),'Reentrega consulta a mesma licença e não inicia outra criação');
select public.finish_care_cycle_step(cycle,(job->>'token')::uuid,(step->>'id')::uuid,false) from d4;
select pg_temp.check_d4((select state='unknown' from public.whatsapp_care_cycle_steps,d4 where id=(step->>'id')::uuid),'Incerteza permanece durável');
do $$begin begin perform public.start_care_cycle_step(cycle,(job->>'token')::uuid,'create','outra',job->>'creator_instance',repeat('a',64)) from d4;raise exception 'FAIL: outra criação concedida';exception when others then if sqlerrm like 'FAIL:%' then raise;end if;raise notice 'PASS: revisão nova não concede segunda criação no mesmo ciclo';end;end $$;
select public.record_care_cycle_creation(cycle,(job->>'token')::uuid,'99887766-5555@g.us',date_trunc('second',clock_timestamp()),(date_trunc('second',clock_timestamp()) at time zone 'UTC'+interval '1 year') at time zone 'UTC') from d4;

-- Contrato pós-entrada: apenas preparo estrutural pode anteceder o cliente.
update public.whatsapp_care_groups set entry_pending=true where id=(select grp from d4);
alter table d4 add snapshot jsonb;
update d4 set body=(select jsonb_build_object('cycleId',c.id,'groupJid',c.group_jid,'customerJid',substring(c.customer_phone from 2)||'@s.whatsapp.net','createdAt',c.created_at,'expiresAt',c.expires_at,'closing',false,'closed',false,'firstViolation',false,'prepared',true,'logoApplied',true,'logoHash',repeat('b',64)) from public.whatsapp_care_cycles c where c.id=d4.cycle),
 snapshot=jsonb_build_object('id','99887766-5555@g.us','locked',true,'adminsAddOnly',true,'approvalRequired',true,'participants',(select jsonb_agg(jsonb_build_object('jid',substring(n->>'phone' from 2)||'@s.whatsapp.net','admin',true)) from jsonb_array_elements(job->'numbers') n));
select public.record_care_cycle_observation(cycle,(job->>'token')::uuid,body,snapshot,'https://chat.whatsapp.com/FICTICIO123456') from d4;
select pg_temp.check_d4((select state='waiting_customer' and not controls_verified from public.whatsapp_care_groups,d4 where id=grp),'Preparo sem mensagem libera espera do cliente, sem confirmar telefone');
select pg_temp.check_d4((select exists(select 1 from public.whatsapp_care_invites where group_id=grp) from d4),'Convite pode existir antes de descrição, mensagem, recibo e pin');
select pg_temp.check_d4((select not public.care_cycle_send_ready(grp) from d4),'Preparação e convite não liberam código/aviso');
update d4 set snapshot=jsonb_set(snapshot,'{participants}',(snapshot->'participants')||jsonb_build_array(jsonb_build_object('jid','5511999999999@s.whatsapp.net','admin',false)));
select public.record_care_cycle_observation(cycle,(job->>'token')::uuid,body,snapshot) from d4;
select pg_temp.check_d4((select state='creating' and not controls_verified and reason='waiting_first_receipt' from public.whatsapp_care_groups,d4 where id=grp),'Entrar no grupo não libera envio antes do acolhimento');
update d4 set step=public.start_care_cycle_step(cycle,(job->>'token')::uuid,'welcome','initial',job->'numbers'->1->>'instance',repeat('c',64));
select public.finish_care_cycle_step(cycle,(job->>'token')::uuid,(step->>'id')::uuid,true,'boas-vindas-primeira') from d4;
update d4 set body=body||jsonb_build_object('firstReceived',true,'firstWelcomeOperation',step->>'id','firstMessageId','boas-vindas-primeira','lastWelcomeOperation',step->>'id','lastWelcomeMessageId','boas-vindas-primeira','welcomeAdmissions',jsonb_build_object((select admission_id::text from public.whatsapp_care_cycles where id=cycle),step->>'id'),'lastWelcomeAdmissionId',(select admission_id from public.whatsapp_care_cycles where id=cycle),'descriptionHash',repeat('d',64),'pinAccepted',true,'pinExpiresAt',now()+interval '1 day');
select public.record_care_cycle_observation(cycle,(job->>'token')::uuid,body,snapshot) from d4;
select pg_temp.check_d4((select not public.care_cycle_send_ready(grp) from d4),'Aceite do envio sem recebimento da admissão atual continua bloqueado');
update d4 set body=body||'{"lastWelcomeReceived":true}';
select public.record_care_cycle_observation(cycle,(job->>'token')::uuid,body,snapshot) from d4;
select pg_temp.check_d4((select public.care_cycle_send_ready(grp) from d4),'Cliente comum + acolhimento recebido + descrição e pin vigentes liberam envio');
select pg_temp.check_d4((select admission_welcome_id=admission_id and admission_welcome_message_id='boas-vindas-primeira' from public.whatsapp_care_cycles,d4 where id=cycle),'Banco conserva prova da admissão e mensagem exatas');
update public.whatsapp_care_cycles set admission_id=gen_random_uuid() where id=(select cycle from d4);
select pg_temp.check_d4((select not public.care_cycle_send_ready(grp) from d4),'Outra admissão invalida a liberação sem reiniciar o grupo');
select public.record_care_cycle_observation(cycle,(job->>'token')::uuid,body,snapshot) from d4;
select pg_temp.check_d4((select not public.care_cycle_send_ready(grp) from d4),'Recibo e mensagem da admissão anterior não acolhem a reentrada');
update d4 set step=public.start_care_cycle_step(cycle,(job->>'token')::uuid,'welcome',(select admission_id::text from public.whatsapp_care_cycles where id=cycle),job->'numbers'->1->>'instance',repeat('e',64));
select public.finish_care_cycle_step(cycle,(job->>'token')::uuid,(step->>'id')::uuid,true,'boas-vindas-retorno') from d4;
update d4 set body=body||jsonb_build_object('lastWelcomeOperation',step->>'id','lastWelcomeMessageId','boas-vindas-retorno','welcomeAdmissions',jsonb_build_object((select admission_id::text from public.whatsapp_care_cycles where id=cycle),step->>'id'),'lastWelcomeAdmissionId',(select admission_id from public.whatsapp_care_cycles where id=cycle),'lastWelcomeReceived',false);
select public.record_care_cycle_observation(cycle,(job->>'token')::uuid,body,snapshot) from d4;
select pg_temp.check_d4((select not public.care_cycle_send_ready(grp) from d4),'Novo acolhimento ainda aguarda recebimento comprovado');
update d4 set body=body||'{"lastWelcomeReceived":true}';
select public.record_care_cycle_observation(cycle,(job->>'token')::uuid,body,snapshot) from d4;
select pg_temp.check_d4((select public.care_cycle_send_ready(grp) from d4),'Recebimento do retorno libera o mesmo ciclo');
select pg_temp.check_d4((select group_jid='99887766-5555@g.us' and expires_at=((created_at at time zone 'UTC')+interval '1 year') at time zone 'UTC' from public.whatsapp_care_cycles,d4 where id=cycle),'JID e ano permanecem intactos após reentrada');
select pg_temp.check_d4(not has_function_privilege('service_role','public.record_care_cycle_observation_before_post_entry(uuid,uuid,jsonb,jsonb,text)','execute'),'Contrato antigo não pode contornar as provas novas');
select pg_temp.check_d4(not has_function_privilege('authenticated','public.record_care_cycle_observation(uuid,uuid,jsonb,jsonb,text)','execute'),'Navegador não registra prova de recebimento');
rollback;
